import React, { useEffect, useState } from "react";
import axios from "axios";

function UserProfile({ email }) {
    // State to store user data
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);


    useEffect(() => {
        if (!email) {
            console.error("Email is undefined");
            return;
        }

        const fetchUserData = async () => {
            try {
                const response = await axios.get(`http://localhost:8000/savings/${email}`);
                setUser(response.data);
            } catch (err) {
                console.error("Error fetching user data:", err);
                setError("Error loading user data. Please try again later.");
            } finally {
                setLoading(false); // Set loading to false regardless of success or failure
            }
        };

        fetchUserData();
    }, [email]);


    // Render user information or loading message
    return (
        <div className="user-profile" email={email}>
            {user ? (
                <div>
                    <h2>User Profile</h2>
                    <p><strong>Name:</strong> {user.name}</p>
                    <p><strong>Father's Name:</strong> {user.fatherName}</p>
                    <p><strong>Mother's Name:</strong> {user.motherName}</p>
                    <p><strong>Date of Birth:</strong> {new Date(user.dob).toLocaleDateString()}</p>
                    <p><strong>Age:</strong> {user.age}</p>
                    <p><strong>Gender:</strong> {user.gender}</p>
                    <p><strong>Balance:</strong> ${user.balance.toFixed(2)}</p>
                </div>
            ) : (
                <p>Loading user data...</p>
            )}
        </div>
    );
}

export default UserProfile;
